/// <summary>
/// Supervisor-only counting operations: variance review, line approval/rejection, recount
/// requests and posting. Kept apart from HSMobileOpsCountTaskService so no counter-facing call
/// can ever return system quantities or values.
///
/// Every operation checks that UserId is an active cycle-count supervisor
/// (HSMobileOpsUser.IsCycleCountSupervisor) - the app hides these screens from everyone else,
/// but that is cosmetic; this check is the boundary.
///
/// Line status (MATCH, MINOR_VARIANCE, RECOUNT_REQUIRED, CONFIRMATION_REQUIRED, INVESTIGATE,
/// APPROVED) comes from lineState over InventJournalTrans, HSMobileOpsCountTolerance and
/// HSMobileOpsCountLineReview. reviewLines records decisions with standard counting reason
/// codes; postJournal refuses while counted lines still need a decision. TODO for the X++
/// owner: ABC class, who counted each line (attempt table), recount assignment.
///
/// Registered as HSMobileOpsCountSupervisorSvc - full service group build required.
/// </summary>
class HSMobileOpsCountSupervisorService
{
}

Method.Source:
public HSMobileOpsCountVarianceResponse getVariance(HSMobileOpsCountVarianceRequest _request)
{
    HSMobileOpsCountVarianceResponse response = new HSMobileOpsCountVarianceResponse();
    HSMobileOpsCountVarianceLine     line;
    List                             lines = new List(Types::Class);
    InventJournalTrans               inventJournalTrans;
    InventDim                        inventDim;
    HSMobileOpsCountLineReview       review;
    HSMobileOpsCountTolerance        tolerance;
    container                        state;
    str                              refusal;

    response.parmSuccess(false);
    response.parmLines(lines);

    refusal = HSMobileOpsCountSupervisorService::refusal(_request ? _request.parmDataAreaId() : '',
        _request ? _request.parmJournalId() : '', _request ? _request.parmUserId() : '', true);
    if (refusal)
    {
        response.parmErrorCode(refusal);
        return response;
    }

    changecompany (_request.parmDataAreaId())
    {
        tolerance = HSMobileOpsCountTolerance::find();
        response.parmCurrencyCode(Ledger::accountingCurrency());
        response.parmToleranceText(tolerance.describe());
        response.parmReasonCodes(HSMobileOpsCountSupervisorService::reasonCodes());

        while select LineNum, ItemId, Counted, InventOnHand, Qty, CostAmount, CountingReasonCode
            from inventJournalTrans
            order by LineNum
            where inventJournalTrans.JournalId == _request.parmJournalId()
            join wMSLocationId, inventBatchId, inventSerialId from inventDim
                where inventDim.InventDimId == inventJournalTrans.InventDimId
        {
            review = HSMobileOpsCountLineReview::find(inventJournalTrans.JournalId, inventJournalTrans.LineNum);
            state  = HSMobileOpsCountSupervisorService::lineState(inventJournalTrans, review, tolerance);

            line = new HSMobileOpsCountVarianceLine();
            line.parmLineNumber(inventJournalTrans.LineNum);
            line.parmItemNumber(inventJournalTrans.ItemId);
            line.parmItemName(InventTable::find(inventJournalTrans.ItemId).itemName());
            line.parmLocationId(inventDim.wMSLocationId);
            line.parmBatchId(inventDim.inventBatchId);
            line.parmSerialId(inventDim.inventSerialId);
            line.parmCountedQty(inventJournalTrans.Counted);
            line.parmSystemQty(inventJournalTrans.InventOnHand);
            line.parmVarianceQty(inventJournalTrans.Qty);
            line.parmVarianceValue(inventJournalTrans.CostAmount);
            line.parmCounted(HSMobileOpsCountSupervisorService::isCounted(inventJournalTrans));
            line.parmToleranceStatus(conPeek(state, 1));
            line.parmRecounted(conPeek(state, 2));
            line.parmRecountQty(conPeek(state, 3));
            line.parmInitialQty(review.RecId ? review.InitialQty : inventJournalTrans.Counted);
            line.parmReviewStatus(review.Decision ? review.Decision : 'PENDING');
            line.parmReasonCode(inventJournalTrans.CountingReasonCode ? inventJournalTrans.CountingReasonCode : review.ReasonCode);
            line.parmComment(review.Comment);
            line.parmReviewedBy(review.ReviewedBy);
            // TODO (X++ owner): ABC class and who counted the line (attempt table).
            line.parmAbcClass('');
            line.parmCountedBy('');
            lines.addEnd(line);
        }
    }

    response.parmLines(lines);
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// APPROVE / RECOUNT / INVESTIGATE / REJECT a set of lines, with an optional standard
/// counting reason code (written to InventJournalTrans so it posts with the line) and a
/// comment (Note). Each decision remembers the counted quantity, so a different count after
/// it is seen: after RECOUNT it is the recount (CONFIRMATION_REQUIRED); after APPROVE it
/// withdraws the approval.
/// TODO (X++ owner): RECOUNT with AssignTo, refusing the previous counter (RECOUNT_SAME_USER).
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountSupervisorResponse reviewLines(HSMobileOpsCountReviewRequest _request)
{
    HSMobileOpsCountSupervisorResponse response = new HSMobileOpsCountSupervisorResponse();
    HSMobileOpsCountLineReview         review;
    HSMobileOpsCountTolerance          tolerance;
    InventJournalTrans                 inventJournalTrans;
    ListEnumerator                     lineNumbers;
    container                          state;
    str                                action;
    str                                refusal;

    response.parmSuccess(false);

    refusal = HSMobileOpsCountSupervisorService::refusal(_request ? _request.parmDataAreaId() : '',
        _request ? _request.parmJournalId() : '', _request ? _request.parmUserId() : '', true);
    if (refusal)
    {
        response.parmErrorCode(refusal);
        return response;
    }
    action = strUpr(_request.parmAction());
    if (!(action == 'APPROVE' || action == 'REJECT' || action == 'RECOUNT' || action == 'INVESTIGATE')
        || !_request.parmLineNumbers() || !_request.parmLineNumbers().elements())
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    changecompany (_request.parmDataAreaId())
    {
        if (_request.parmReasonCode() && !InventCountingReasonCode::exist(_request.parmReasonCode()))
        {
            response.parmErrorCode('INVALID_REASON_CODE');
            return response;
        }
        tolerance = HSMobileOpsCountTolerance::find();

        ttsbegin;
        lineNumbers = _request.parmLineNumbers().getEnumerator();
        while (lineNumbers.moveNext())
        {
            select firstOnly forUpdate inventJournalTrans
                where inventJournalTrans.JournalId == _request.parmJournalId()
                   && inventJournalTrans.LineNum   == lineNumbers.current();
            if (!inventJournalTrans.RecId)
            {
                ttsabort;
                response.parmErrorCode('LINE_NOT_FOUND');
                response.parmMessage(strFmt('Line %1 is not on this journal.', lineNumbers.current()));
                return response;
            }

            review = HSMobileOpsCountLineReview::find(inventJournalTrans.JournalId, inventJournalTrans.LineNum, true);
            state  = HSMobileOpsCountSupervisorService::lineState(inventJournalTrans, review, tolerance);
            if (!review.RecId)
            {
                review.JournalId  = inventJournalTrans.JournalId;
                review.LineNum    = inventJournalTrans.LineNum;
                review.InitialQty = inventJournalTrans.Counted;
            }
            if (conPeek(state, 2))
            {
                // The recount asked for earlier has been done - keep it.
                review.Recounted  = NoYes::Yes;
                review.RecountQty = conPeek(state, 3);
            }
            if (action == 'RECOUNT')
            {
                review.Recounted = NoYes::No;
            }

            if (_request.parmReasonCode() && inventJournalTrans.CountingReasonCode != _request.parmReasonCode())
            {
                inventJournalTrans.CountingReasonCode = _request.parmReasonCode();
                inventJournalTrans.update();
            }

            review.Decision          = action == 'APPROVE' ? 'APPROVED' : (action == 'REJECT' ? 'REJECTED' : action);
            review.ReasonCode        = _request.parmReasonCode() ? _request.parmReasonCode() : review.ReasonCode;
            review.Comment           = _request.parmNote() ? _request.parmNote() : review.Comment;
            review.ReviewedBy        = _request.parmUserId();
            review.ReviewedAtUtc     = DateTimeUtil::utcNow();
            review.DecisionCountedQty = inventJournalTrans.Counted;
            review.write();
        }
        ttscommit;
    }

    response.parmSuccess(true);
    return response;
}

/// <summary>
/// Posts the counting journal with the standard journal check/post. Refused when it is
/// already posted, gone, or has counted lines still needing a decision (LINES_NEED_APPROVAL).
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountSupervisorResponse postJournal(HSMobileOpsCountPostRequest _request)
{
    HSMobileOpsCountSupervisorResponse response = new HSMobileOpsCountSupervisorResponse();
    InventJournalTable                 inventJournalTable;
    JournalCheckPost                   journalCheckPost;
    str                                refusal;
    int                                infologStart;
    int                                unapproved;

    response.parmSuccess(false);

    refusal = HSMobileOpsCountSupervisorService::refusal(_request ? _request.parmDataAreaId() : '',
        _request ? _request.parmJournalId() : '', _request ? _request.parmUserId() : '', true);
    if (refusal)
    {
        response.parmErrorCode(refusal);
        return response;
    }

    changecompany (_request.parmDataAreaId())
    {
        unapproved = HSMobileOpsCountDualEngine::isDual(_request.parmJournalId())
            ? HSMobileOpsCountDualEngine::unresolvedLines(_request.parmJournalId())
            : HSMobileOpsCountSupervisorService::unapprovedLines(_request.parmJournalId());
        if (unapproved)
        {
            response.parmErrorCode('LINES_NEED_APPROVAL');
            response.parmMessage(strFmt('%1 line(s) still need a decision before posting.', unapproved));
            return response;
        }

        inventJournalTable = InventJournalTable::find(_request.parmJournalId());
        infologStart = infologLine();
        // A wall-to-wall count posts in batch, which releases its warehouse when it has posted.
        if (inventJournalTable.HSMobileOpsWallToWall)
        {
            try
            {
                HSMobileOpsCountWallToWall::requestPost(inventJournalTable.InventLocationId);
            }
            catch (Exception::Error)
            {
                response.parmErrorCode('POST_FAILED');
                response.parmMessage(HSMobileOpsCountSupervisorService::infologSince(infologStart));
                return response;
            }
            response.parmSuccess(true);
            response.parmMessage(strFmt('%1 is posting in batch. %2 is released when it has posted.',
                inventJournalTable.JournalId, inventJournalTable.InventLocationId));
            return response;
        }
        try
        {
            journalCheckPost = InventJournalCheckPost::newPostJournal(inventJournalTable);
            journalCheckPost.parmThrowCheckFailed(true);
            journalCheckPost.runOperation();
        }
        catch (Exception::Error)
        {
            response.parmErrorCode('POST_FAILED');
            response.parmMessage(HSMobileOpsCountSupervisorService::infologSince(infologStart));
            return response;
        }

        if (InventJournalTable::find(_request.parmJournalId()).Posted != NoYes::Yes)
        {
            response.parmErrorCode('POST_FAILED');
            response.parmMessage(HSMobileOpsCountSupervisorService::infologSince(infologStart));
            return response;
        }
    }

    response.parmSuccess(true);
    return response;
}

/// <summary>
/// A dual count journal: how its lines stand, and those needing a decision with every count
/// side by side. Supervisors only. This is the only call that returns other people's counts.
/// </summary>
public HSMobileOpsCountVarianceSummaryResponse getVarianceSummary(HSMobileOpsCountVarianceRequest _request)
{
    HSMobileOpsCountVarianceSummaryResponse response = new HSMobileOpsCountVarianceSummaryResponse();
    HSMobileOpsCountVarianceSummaryLine     line;
    HSMobileOpsCountAttemptRow           attemptRow;
    List                        lines = new List(Types::Class);
    List                        attempts;
    InventJournalTrans          journalTrans;
    InventDim                   inventDim;
    HSMobileOpsCountAttempt              attempt;
    str                         refusal;
    int                         total;

    response.parmSuccess(false);
    response.parmLines(lines);

    refusal = HSMobileOpsCountSupervisorService::refusal(_request ? _request.parmDataAreaId() : '',
        _request ? _request.parmJournalId() : '', _request ? _request.parmUserId() : '', false);
    if (refusal)
    {
        response.parmErrorCode(refusal);
        return response;
    }

    changecompany (_request.parmDataAreaId())
    {
        while select count(RecId), HSMobileOpsCountStatus from journalTrans
            group by HSMobileOpsCountStatus
            where journalTrans.JournalId == _request.parmJournalId()
        {
            total += int642int(journalTrans.RecId);
            switch (journalTrans.HSMobileOpsCountStatus)
            {
                case HSMobileOpsCountStatus::Open:           response.parmOpenLines(int642int(journalTrans.RecId));      break;
                case HSMobileOpsCountStatus::FirstCounted:   response.parmFirstCounted(int642int(journalTrans.RecId));   break;
                case HSMobileOpsCountStatus::Matched:        response.parmMatched(int642int(journalTrans.RecId));        break;
                case HSMobileOpsCountStatus::Mismatch:       response.parmMismatch(int642int(journalTrans.RecId));       break;
                case HSMobileOpsCountStatus::Recount:        response.parmRecount(int642int(journalTrans.RecId));        break;
                case HSMobileOpsCountStatus::Approved:       response.parmApproved(int642int(journalTrans.RecId));       break;
                case HSMobileOpsCountStatus::EmptyConfirmed: response.parmEmptyConfirmed(int642int(journalTrans.RecId)); break;
            }
        }
        response.parmTotalLines(total);

        journalTrans.clear();
        while select RecId, LineNum, ItemId, InventOnHand, HSMobileOpsCountStatus, HSMobileOpsAttemptCount from journalTrans
            order by LineNum
            where journalTrans.JournalId == _request.parmJournalId()
               && (journalTrans.HSMobileOpsCountStatus == HSMobileOpsCountStatus::Mismatch
                || journalTrans.HSMobileOpsCountStatus == HSMobileOpsCountStatus::Recount)
            join wMSLocationId, inventBatchId, inventSerialId, configId, InventSizeId, InventColorId, InventStyleId from inventDim
                where inventDim.inventDimId == journalTrans.InventDimId
        {
            if (lines.elements() >= 500)
            {
                response.parmTruncated(true);
                break;
            }
            attempts = new List(Types::Class);
            while select AttemptNo, CountedQty, UserId, CountedDateTime from attempt
                order by AttemptNo
                where attempt.InventJournalTransRecId == journalTrans.RecId
            {
                attemptRow = new HSMobileOpsCountAttemptRow();
                attemptRow.parmAttemptNo(attempt.AttemptNo);
                attemptRow.parmCountedQty(attempt.CountedQty);
                attemptRow.parmUserId(attempt.UserId);
                attemptRow.parmCountedDateTime(DateTimeUtil::toStr(attempt.CountedDateTime));
                attempts.addEnd(attemptRow);
            }
            line = new HSMobileOpsCountVarianceSummaryLine();
            line.parmLineNumber(journalTrans.LineNum);
            line.parmItemNumber(journalTrans.ItemId);
            line.parmItemName(InventTable::find(journalTrans.ItemId).itemName());
            line.parmLocationId(inventDim.wMSLocationId);
            line.parmBatchId(inventDim.inventBatchId);
            line.parmSerialId(inventDim.inventSerialId);
            line.parmConfigId(inventDim.configId);
            line.parmSizeId(inventDim.InventSizeId);
            line.parmColorId(inventDim.InventColorId);
            line.parmStyleId(inventDim.InventStyleId);
            line.parmStatus(enum2Symbol(enumNum(HSMobileOpsCountStatus), journalTrans.HSMobileOpsCountStatus));
            line.parmSystemQty(journalTrans.InventOnHand);
            line.parmNeedsApproval(journalTrans.HSMobileOpsCountStatus == HSMobileOpsCountStatus::Mismatch && journalTrans.HSMobileOpsAttemptCount >= 3);
            line.parmAttempts(attempts);
            lines.addEnd(line);
        }
    }
    response.parmLines(lines);
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// A supervisor settles a disagreement: APPROVE makes FinalQty the count, RECOUNT sends the
/// line back to the counters. Only for lines that disagree. Never posts.
/// </summary>
[Wrappable(false), Hookable(false)]
public HSMobileOpsCountSupervisorResponse approveLine(HSMobileOpsCountApproveRequest _request)
{
    HSMobileOpsCountSupervisorResponse response = new HSMobileOpsCountSupervisorResponse();
    InventJournalTrans                 journalTrans;
    str                                action;
    str                                refusal;

    response.parmSuccess(false);

    refusal = HSMobileOpsCountSupervisorService::refusal(_request ? _request.parmDataAreaId() : '',
        _request ? _request.parmJournalId() : '', _request ? _request.parmUserId() : '', true);
    if (refusal)
    {
        response.parmErrorCode(refusal);
        return response;
    }
    action = strUpr(_request.parmAction());
    if ((action != 'APPROVE' && action != 'RECOUNT') || _request.parmFinalQty() < 0)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    changecompany (_request.parmDataAreaId())
    {
        if (_request.parmReasonCode() && !InventCountingReasonCode::exist(_request.parmReasonCode()))
        {
            response.parmErrorCode('INVALID_REASON_CODE');
            return response;
        }
        ttsbegin;
        select forUpdate firstOnly journalTrans
            where journalTrans.JournalId == _request.parmJournalId()
               && journalTrans.LineNum   == _request.parmLineNumber();
        if (!journalTrans.RecId)
        {
            ttsabort;
            response.parmErrorCode('LINE_NOT_FOUND');
            return response;
        }
        if (journalTrans.HSMobileOpsCountStatus != HSMobileOpsCountStatus::Mismatch
         && journalTrans.HSMobileOpsCountStatus != HSMobileOpsCountStatus::Recount)
        {
            ttsabort;
            response.parmErrorCode('LINE_NOT_IN_DISPUTE');
            response.parmMessage(strFmt('Line %1 is %2.', journalTrans.LineNum, journalTrans.HSMobileOpsCountStatus));
            return response;
        }
        if (_request.parmReasonCode())
        {
            journalTrans.CountingReasonCode = _request.parmReasonCode();
        }
        if (action == 'APPROVE')
        {
            HSMobileOpsCountDualEngine::settleLine(journalTrans, _request.parmFinalQty(), HSMobileOpsCountStatus::Approved);
        }
        else
        {
            journalTrans.HSMobileOpsCountStatus = HSMobileOpsCountStatus::Recount;
            journalTrans.doUpdate();
        }
        ttscommit;
    }
    response.parmSuccess(true);
    response.parmAffected(1);
    return response;
}

/// <summary>
/// Count accuracy for a warehouse and date range, grouped by LOCATION or ITEM: of the posted
/// counting lines in the range, the share with no adjustment (Qty = 0), and the absolute
/// adjusted cost. A simple, real fallback over standard tables. TODO (X++ owner): ABC_CLASS
/// and COUNTER grouping (they need the ABC classification and the attempt table), the
/// per-class tolerance text per row, and your own accuracy definition if it differs.
/// </summary>
public HSMobileOpsCountAccuracyResponse getAccuracyReport(HSMobileOpsCountAccuracyRequest _request)
{
    HSMobileOpsCountAccuracyResponse response = new HSMobileOpsCountAccuracyResponse();
    HSMobileOpsCountAccuracyRow      row;
    List                             rows = new List(Types::Class);
    Map                              groups = new Map(Types::String, Types::Container);
    MapEnumerator                    groupEnumerator;
    InventJournalTrans               inventJournalTrans;
    InventJournalTable               inventJournalTable;
    InventDim                        inventDim;
    HSMobileOpsUser                  user;
    container                        totals;
    str                              groupBy;
    str                              key;
    TransDate                        fromDate;
    TransDate                        toDate;
    int                              counted;
    int                              accurate;
    int                              allCounted;
    int                              allAccurate;
    real                             value;

    response.parmSuccess(false);
    response.parmRows(rows);

    if (!_request || !_request.parmDataAreaId() || !_request.parmUserId() || !_request.parmWarehouseId()
        || !CompanyInfo::findDataArea(_request.parmDataAreaId()).RecId)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    // HSMobileOpsUser is per company - looked up in the request's company, as signIn does.
    changecompany (_request.parmDataAreaId())
    {
        user = HSMobileOpsUser::find(_request.parmUserId());
    }
    if (!user.RecId || !user.IsActive || !user.IsCycleCountSupervisor || user.IsExternalCounter)
    {
        response.parmErrorCode('NOT_SUPERVISOR');
        return response;
    }

    groupBy = _request.parmGroupBy();
    if (groupBy != 'LOCATION' && groupBy != 'ITEM')
    {
        response.parmErrorCode('GROUPING_NOT_AVAILABLE');
        return response;
    }

    fromDate = str2Date(_request.parmFromDate(), 321);
    toDate   = str2Date(_request.parmToDate(), 321);
    if (!fromDate || !toDate || fromDate > toDate)
    {
        response.parmErrorCode('INVALID_REQUEST');
        return response;
    }

    changecompany (_request.parmDataAreaId())
    {
        response.parmCurrencyCode(Ledger::accountingCurrency());

        while select ItemId, Qty, CostAmount from inventJournalTrans
            where inventJournalTrans.TransDate >= fromDate
               && inventJournalTrans.TransDate <= toDate
            join wMSLocationId from inventDim
                where inventDim.InventDimId      == inventJournalTrans.InventDimId
                   && inventDim.InventLocationId == _request.parmWarehouseId()
            exists join inventJournalTable
                where inventJournalTable.JournalId   == inventJournalTrans.JournalId
                   && inventJournalTable.JournalType == InventJournalType::Count
                   && inventJournalTable.Posted      == NoYes::Yes
        {
            key = groupBy == 'ITEM' ? inventJournalTrans.ItemId : inventDim.wMSLocationId;
            totals = groups.exists(key) ? groups.lookup(key) : [0, 0, 0.0];

            counted  = conPeek(totals, 1) + 1;
            accurate = conPeek(totals, 2) + (inventJournalTrans.Qty == 0 ? 1 : 0);
            value    = conPeek(totals, 3) + abs(inventJournalTrans.CostAmount);
            groups.insert(key, [counted, accurate, value]);
        }

        groupEnumerator = groups.getEnumerator();
        while (groupEnumerator.moveNext())
        {
            key      = groupEnumerator.currentKey();
            totals   = groupEnumerator.currentValue();
            counted  = conPeek(totals, 1);
            accurate = conPeek(totals, 2);

            row = new HSMobileOpsCountAccuracyRow();
            row.parmGroupKey(key);
            row.parmLabel(groupBy == 'ITEM' ? InventTable::find(key).itemName() : (key ? key : '(no location)'));
            row.parmCountedLines(counted);
            row.parmAccurateLines(accurate);
            row.parmAccuracyPct(counted ? accurate * 100.0 / counted : 0);
            row.parmVarianceValue(conPeek(totals, 3));
            row.parmTolerance('');
            rows.addEnd(row);

            allCounted  += counted;
            allAccurate += accurate;
        }
    }

    response.parmRows(rows);
    response.parmCountedLines(allCounted);
    response.parmAccurateLines(allAccurate);
    response.parmOverallPct(allCounted ? allAccurate * 100.0 / allCounted : 0);
    response.parmSuccess(true);
    return response;
}

/// <summary>
/// [status, recountDone, recountQty] for one line. Status is one of NOT_COUNTED, MATCH,
/// MINOR_VARIANCE, RECOUNT_REQUIRED, CONFIRMATION_REQUIRED, INVESTIGATE, APPROVED. The only
/// place these rules live - getVariance shows them and postJournal enforces them.
/// </summary>
public static container lineState(InventJournalTrans _trans, HSMobileOpsCountLineReview _review, HSMobileOpsCountTolerance _tolerance)
{
    // A different count since the decision (see HSMobileOpsCountLineReview).
    boolean changedSince = _review.RecId && _trans.Counted != _review.DecisionCountedQty;
    boolean recountDone  = _review.Decision == 'RECOUNT' && changedSince;
    real    recountQty   = recountDone ? _trans.Counted : (_review.Recounted ? _review.RecountQty : 0);
    boolean recounted    = recountDone || _review.Recounted == NoYes::Yes;

    if (!HSMobileOpsCountSupervisorService::isCounted(_trans))
    {
        return ['NOT_COUNTED', recounted, recountQty];
    }
    if (_review.Decision == 'APPROVED')
    {
        return [changedSince ? 'CONFIRMATION_REQUIRED' : 'APPROVED', recounted, recountQty];
    }
    if (_review.Decision == 'RECOUNT')
    {
        return [recountDone ? 'CONFIRMATION_REQUIRED' : 'RECOUNT_REQUIRED', recounted, recountQty];
    }
    if (_review.Decision == 'INVESTIGATE')
    {
        return ['INVESTIGATE', recounted, recountQty];
    }
    if (_review.Decision == 'REJECTED')
    {
        return ['RECOUNT_REQUIRED', recounted, recountQty];
    }
    if (_trans.Qty == 0)
    {
        return ['MATCH', recounted, recountQty];
    }
    if (_tolerance.withinTolerance(_trans.Qty, _trans.InventOnHand))
    {
        return ['MINOR_VARIANCE', recounted, recountQty];
    }
    return ['RECOUNT_REQUIRED', recounted, recountQty];
}

/// <summary>
/// Whether a count has been entered: a counted quantity, or a variance (a counted zero).
/// TODO (X++ owner): an explicit counted flag from the attempt table.
/// </summary>
public static boolean isCounted(InventJournalTrans _trans)
{
    return _trans.Counted != 0 || _trans.Qty != 0;
}

/// <summary>
/// The company's standard counting reason codes (Inventory management > Setup > Counting
/// reason codes), for the review picker.
/// </summary>
private static List reasonCodes()
{
    List                       codes = new List(Types::Class);
    InventCountingReasonCode   reason;
    HSMobileOpsCountReasonCode code;

    while select ReasonCode, Description from reason order by ReasonCode
    {
        code = new HSMobileOpsCountReasonCode();
        code.parmCode(reason.ReasonCode);
        code.parmDescription(reason.Description);
        codes.addEnd(code);
    }
    return codes;
}

/// <summary>
/// How many counted lines still need a decision before the journal may post: anything that
/// is not MATCH, MINOR_VARIANCE or APPROVED.
/// </summary>
private static int unapprovedLines(InventJournalId _journalId)
{
    InventJournalTrans        inventJournalTrans;
    HSMobileOpsCountTolerance tolerance = HSMobileOpsCountTolerance::find();
    str                       status;
    int                       pending;

    while select inventJournalTrans
        where inventJournalTrans.JournalId == _journalId
    {
        status = conPeek(HSMobileOpsCountSupervisorService::lineState(inventJournalTrans,
            HSMobileOpsCountLineReview::find(_journalId, inventJournalTrans.LineNum), tolerance), 1);
        if (!(status == 'NOT_COUNTED' || status == 'MATCH' || status == 'MINOR_VARIANCE' || status == 'APPROVED'))
        {
            pending++;
        }
    }
    return pending;
}

/// <summary>
/// The error code that ends a supervisor request before it starts, or '' to go ahead.
/// </summary>
private static str refusal(DataAreaId _company, InventJournalId _journalId, str _userId, boolean _mustBeOpen)
{
    HSMobileOpsUser user;
    str             state;

    if (!_company || !_journalId || !_userId || !CompanyInfo::findDataArea(_company).RecId)
    {
        return 'INVALID_REQUEST';
    }

    // HSMobileOpsUser is per company - looked up in the request's company, as signIn does.
    changecompany (_company)
    {
        user = HSMobileOpsUser::find(_userId);
    }
    // An external counter is never a supervisor, whatever else is ticked.
    if (!user.RecId || !user.IsActive || !user.IsCycleCountSupervisor || user.IsExternalCounter)
    {
        return 'NOT_SUPERVISOR';
    }

    state = HSMobileOpsCountTaskService::journalState(_company, _journalId);
    if (state == HSMobileOpsCountTaskService::stateNotFound())
    {
        return 'JOURNAL_NOT_FOUND';
    }
    if (_mustBeOpen && state == HSMobileOpsCountTaskService::statePosted())
    {
        return 'JOURNAL_POSTED';
    }
    return '';
}

/// <summary>
/// What the infolog said after [_from] - the posting's own reason for refusing.
/// </summary>
private static str infologSince(int _from)
{
    str text;
    int i;

    for (i = _from + 1; i <= infologLine(); i++)
    {
        text += infolog.text(i) + ' ';
    }
    return strLRTrim(text) ? strLRTrim(text) : 'The journal could not be posted.';
}
